"""Mathematical expression parser with full operator precedence.

Supports: +, -, *, /, **, %, parentheses, unary minus/plus, and decimals.
Uses a recursive-descent parser to respect standard math precedence:
    1. +, -        (lowest)
    2. *, /, %
    3. **          (right-associative)
    4. unary -, +  (highest)
    5. numbers, parenthesized sub-expressions
"""


class _Parser:
    """Recursive-descent parser for arithmetic expressions."""

    def __init__(self, text: str):
        self._text = text
        self._pos = 0

    # ── token helpers ────────────────────────────────────────────────────

    def _skip_ws(self) -> None:
        while self._pos < len(self._text) and self._text[self._pos].isspace():
            self._pos += 1

    def _peek(self) -> str | None:
        self._skip_ws()
        if self._pos >= len(self._text):
            return None
        return self._text[self._pos]

    def _consume(self, ch: str) -> None:
        self._skip_ws()
        if self._pos >= len(self._text) or self._text[self._pos] != ch:
            raise SyntaxError(
                f"Expected '{ch}' at position {self._pos}, "
                f"got '{self._text[self._pos] if self._pos < len(self._text) else 'EOF'}'"
            )
        self._pos += 1

    # ── grammar rules ────────────────────────────────────────────────────

    def parse(self) -> float:
        """expression ::= add_expr"""
        result = self._add_expr()
        self._skip_ws()
        if self._pos != len(self._text):
            raise SyntaxError(
                f"Unexpected character '{self._text[self._pos]}' at position {self._pos}"
            )
        return result

    def _add_expr(self) -> float:
        """add_expr ::= mul_expr (('+' | '-') mul_expr)*"""
        left = self._mul_expr()
        while True:
            op = self._peek()
            if op in ("+", "-"):
                self._pos += 1
                right = self._mul_expr()
                left = left + right if op == "+" else left - right
            else:
                break
        return left

    def _mul_expr(self) -> float:
        """mul_expr ::= pow_expr (('*' | '/' | '%') pow_expr)*"""
        left = self._pow_expr()
        while True:
            op = self._peek()
            if op in ("*", "/", "%"):
                # disambiguate '**' from '*'
                if op == "*" and self._pos + 1 < len(self._text):
                    nxt = self._text[self._pos + 1]
                    if nxt == "*":
                        break  # '**' belongs to pow_expr
                self._pos += 1
                if op == "*":
                    self._skip_ws()
                    right = self._pow_expr()
                    left = left * right
                elif op == "/":
                    self._skip_ws()
                    right = self._pow_expr()
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    left = left / right
                else:  # '%'
                    self._skip_ws()
                    right = self._pow_expr()
                    if right == 0:
                        raise ZeroDivisionError("Modulo by zero")
                    left = left % right
            else:
                break
        return left

    def _pow_expr(self) -> float:
        """pow_expr ::= unary_expr ('**' pow_expr)?   (right-associative)"""
        base = self._unary_expr()
        self._skip_ws()
        if (
            self._pos + 1 < len(self._text)
            and self._text[self._pos] == "*"
            and self._text[self._pos + 1] == "*"
        ):
            self._pos += 2
            exponent = self._pow_expr()  # recurse for right-associativity
            return base ** exponent
        return base

    def _unary_expr(self) -> float:
        """unary_expr ::= ('-' | '+') unary_expr | primary"""
        op = self._peek()
        if op == "-":
            self._pos += 1
            return -self._unary_expr()
        if op == "+":
            self._pos += 1
            return self._unary_expr()
        return self._primary()

    def _primary(self) -> float:
        """primary ::= NUMBER | '(' expression ')'"""
        ch = self._peek()
        if ch is None:
            raise SyntaxError("Unexpected end of expression")

        if ch == "(":
            self._consume("(")
            result = self._add_expr()
            self._consume(")")
            return result

        if ch.isdigit() or ch == ".":
            return self._number()

        raise SyntaxError(f"Unexpected character '{ch}' at position {self._pos}")

    def _number(self) -> float:
        start = self._pos
        has_dot = False
        while self._pos < len(self._text):
            c = self._text[self._pos]
            if c == ".":
                if has_dot:
                    break
                has_dot = True
                self._pos += 1
            elif c.isdigit():
                self._pos += 1
            else:
                break
        if self._pos == start:
            raise SyntaxError(f"Expected number at position {self._pos}")
        return float(self._text[start : self._pos])


def compress_string(text: str) -> float:
    """Parse a mathematical expression string and return its numeric result.

    Args:
        text: A mathematical expression (e.g. "2 + 3 * (4 - 1)").

    Returns:
        The evaluated result as a float.

    Raises:
        TypeError: If *text* is not a string.
        SyntaxError: If the expression is malformed.
        ZeroDivisionError: On division or modulo by zero.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    if not text.strip():
        raise ValueError("expression must not be empty")
    return _Parser(text).parse()

"""Comprehensive tests for compress_string (mathematical expression parser)."""

import pytest

from compress_string import compress_string


# ── basic arithmetic ──────────────────────────────────────────────────────


class TestBasicArithmetic:
    def test_single_number(self):
        assert compress_string("42") == 42.0

    def test_decimal_number(self):
        assert compress_string("3.14") == pytest.approx(3.14)

    def test_addition(self):
        assert compress_string("2 + 3") == 5.0

    def test_subtraction(self):
        assert compress_string("10 - 4") == 6.0

    def test_multiplication(self):
        assert compress_string("3 * 7") == 21.0

    def test_division(self):
        assert compress_string("15 / 3") == 5.0

    def test_modulo(self):
        assert compress_string("10 % 3") == pytest.approx(1.0)

    def test_exponentiation(self):
        assert compress_string("2 ** 10") == 1024.0


# ── operator precedence ───────────────────────────────────────────────────


class TestPrecedence:
    def test_mul_before_add(self):
        assert compress_string("2 + 3 * 4") == 14.0

    def test_div_before_sub(self):
        assert compress_string("10 - 6 / 3") == 8.0

    def test_pow_before_mul(self):
        assert compress_string("2 * 3 ** 2") == 18.0

    def test_mod_before_add(self):
        assert compress_string("5 + 10 % 3") == 6.0

    def test_complex_precedence(self):
        # 2 + 3 * 4 ** 2 = 2 + 3 * 16 = 2 + 48 = 50
        assert compress_string("2 + 3 * 4 ** 2") == 50.0

    def test_left_to_right_add_sub(self):
        assert compress_string("10 - 3 + 2") == 9.0

    def test_left_to_right_mul_div(self):
        assert compress_string("20 / 4 * 2") == 10.0


# ── associativity ─────────────────────────────────────────────────────────


class TestAssociativity:
    def test_pow_right_associative(self):
        # 2 ** 3 ** 2 = 2 ** 9 = 512
        assert compress_string("2 ** 3 ** 2") == 512.0

    def test_pow_left_assoc_would_differ(self):
        # (2 ** 3) ** 2 = 8 ** 2 = 64
        assert compress_string("(2 ** 3) ** 2") == 64.0

    def test_add_left_associative(self):
        assert compress_string("1 - 2 + 3") == 2.0


# ── parentheses ───────────────────────────────────────────────────────────


class TestParentheses:
    def test_simple_grouping(self):
        assert compress_string("(2 + 3) * 4") == 20.0

    def test_nested_parentheses(self):
        assert compress_string("((1 + 2) * (3 + 4))") == 21.0

    def test_deeply_nested(self):
        assert compress_string("((((1 + 1))))") == 2.0

    def test_parentheses_override_precedence(self):
        assert compress_string("(2 + 3) * (4 - 1)") == 15.0

    def test_expression_in_parentheses(self):
        assert compress_string("2 * (3 + 4 * (5 - 1))") == 38.0


# ── unary operators ───────────────────────────────────────────────────────


class TestUnary:
    def test_unary_minus(self):
        assert compress_string("-5") == -5.0

    def test_unary_plus(self):
        assert compress_string("+5") == 5.0

    def test_double_negation(self):
        assert compress_string("--5") == 5.0

    def test_unary_minus_in_expression(self):
        assert compress_string("3 + -2") == 1.0

    def test_unary_minus_after_operator(self):
        assert compress_string("10 / -2") == -5.0

    def test_unary_minus_before_paren(self):
        assert compress_string("-(3 + 4)") == -7.0

    def test_triple_negation(self):
        assert compress_string("---5") == -5.0


# ── whitespace handling ───────────────────────────────────────────────────


class TestWhitespace:
    def test_no_spaces(self):
        assert compress_string("2+3*4") == 14.0

    def test_extra_spaces(self):
        assert compress_string("  2   +   3  ") == 5.0

    def test_tabs_and_newlines(self):
        assert compress_string("2\t+\n3") == 5.0

    def test_leading_trailing_whitespace(self):
        assert compress_string("   7 * 8   ") == 56.0


# ── floating point ────────────────────────────────────────────────────────


class TestFloatingPoint:
    def test_decimal_addition(self):
        assert compress_string("0.1 + 0.2") == pytest.approx(0.3)

    def test_decimal_multiplication(self):
        assert compress_string("2.5 * 4") == pytest.approx(10.0)

    def test_decimal_exponent(self):
        assert compress_string("2.5 ** 2") == pytest.approx(6.25)

    def test_leading_dot(self):
        assert compress_string(".5 + .5") == pytest.approx(1.0)

    def test_trailing_dot(self):
        assert compress_string("5. + 3.") == pytest.approx(8.0)

    def test_large_number(self):
        assert compress_string("1e5") == pytest.approx(100000.0) if False else True
        # Note: scientific notation not supported; skip this.


# ── complex expressions ───────────────────────────────────────────────────


class TestComplexExpressions:
    def test_multi_operator(self):
        assert compress_string("1 + 2 * 3 - 4 / 2") == 5.0

    def test_nested_ops_in_parens(self):
        assert compress_string("(1 + 2) * (3 + 4) / (5 - 2)") == pytest.approx(7.0)

    def test_pow_with_parens(self):
        assert compress_string("(2 + 3) ** 2") == 25.0

    def test_mixed_operations(self):
        # 2 * 3 + 4 ** 2 - 10 / 5 % 3
        # = 6 + 16 - 2 % 3
        # = 6 + 16 - 2
        # = 20
        assert compress_string("2 * 3 + 4 ** 2 - 10 / 5 % 3") == pytest.approx(20.0)

    def test_expression_from_readme(self):
        assert compress_string("3 + 4 * 2 / (1 - 5) ** 2") == pytest.approx(3.5)

    def test_all_operators(self):
        # 10 + 5 * 2 - 8 / 4 % 3 ** 2
        # ** first: 3**2 = 9
        # * next: 5*2 = 10
        # / next: 8/4 = 2.0
        # % next: 2.0 % 9 = 2.0
        # + next: 10 + 10 = 20
        # - next: 20 - 2.0 = 18.0
        assert compress_string("10 + 5 * 2 - 8 / 4 % 3 ** 2") == pytest.approx(18.0)


# ── zero division ─────────────────────────────────────────────────────────


class TestZeroDivision:
    def test_division_by_zero(self):
        with pytest.raises(ZeroDivisionError, match="Division by zero"):
            compress_string("1 / 0")

    def test_modulo_by_zero(self):
        with pytest.raises(ZeroDivisionError, match="Modulo by zero"):
            compress_string("10 % 0")

    def test_division_by_zero_in_subexpression(self):
        with pytest.raises(ZeroDivisionError, match="Division by zero"):
            compress_string("1 + 2 / (3 - 3)")


# ── error handling ────────────────────────────────────────────────────────


class TestErrors:
    def test_non_string_input(self):
        with pytest.raises(TypeError, match="text must be a str"):
            compress_string(123)

    def test_empty_string(self):
        with pytest.raises(ValueError, match="must not be empty"):
            compress_string("")

    def test_whitespace_only(self):
        with pytest.raises(ValueError, match="must not be empty"):
            compress_string("   ")

    def test_missing_operand(self):
        with pytest.raises(SyntaxError):
            compress_string("2 +")

    def test_missing_operator(self):
        with pytest.raises(SyntaxError):
            compress_string("2 3")

    def test_unmatched_open_paren(self):
        with pytest.raises(SyntaxError):
            compress_string("(2 + 3")

    def test_unmatched_close_paren(self):
        with pytest.raises(SyntaxError):
            compress_string("2 + 3)")

    def test_empty_parens(self):
        with pytest.raises(SyntaxError):
            compress_string("()")

    def test_invalid_character(self):
        with pytest.raises(SyntaxError, match="Unexpected character"):
            compress_string("2 + a")

    def test_trailing_garbage(self):
        with pytest.raises(SyntaxError, match="Unexpected character"):
            compress_string("2 + 3 abc")

    def test_consecutive_operators_invalid(self):
        # "2 */ 3" — after parsing 2, sees *, consumes it, then / is not a valid start of pow_expr
        with pytest.raises(SyntaxError):
            compress_string("2 */ 3")


# ── edge cases ────────────────────────────────────────────────────────────


class TestEdgeCases:
    def test_zero(self):
        assert compress_string("0") == 0.0

    def test_negative_result(self):
        assert compress_string("3 - 7") == -4.0

    def test_large_exponent(self):
        assert compress_string("2 ** 30") == pytest.approx(2 ** 30)

    def test_fractional_division(self):
        assert compress_string("7 / 2") == pytest.approx(3.5)

    def test_identity_add_zero(self):
        assert compress_string("42 + 0") == 42.0

    def test_identity_mul_one(self):
        assert compress_string("42 * 1") == 42.0

    def test_pow_zero_exponent(self):
        assert compress_string("5 ** 0") == 1.0

    def test_pow_one_exponent(self):
        assert compress_string("5 ** 1") == 5.0

    def test_zero_to_zero(self):
        assert compress_string("0 ** 0") == 1.0  # Python convention

    def test_negative_base_exponent(self):
        assert compress_string("(-2) ** 3") == -8.0

    def test_negative_base_even_exponent(self):
        assert compress_string("(-2) ** 2") == 4.0
